// Runtime.ts: Runner.run (one job run)
const resolved = effective(component, yield* settings.current)   // live config
if (!resolved.enabled) return yield* new ComponentDisabled(...)
const model = options.model ?? resolved.agent.model             // bake-off override wins

const body = Effect.gen(function*() {
  yield* fs.makeDirectory(runDir, { recursive: true })
  yield* runtimeEvent(..., "job.started", { input, model })
  const outcome = yield* job.start(input, context).pipe(Effect.provideContext(services), Effect.exit)
  const seconds = (Date.now() - started) / 1000
  if (outcome._tag === "Success") {
    yield* runtimeEvent(..., "job.succeeded", { model, seconds })
    return { run: runId, ok: true }
  }
  const failure = Cause.findErrorOption(outcome.cause)
  yield* runtimeEvent(..., "job.failed", { model, seconds, error: failure.value._tag, message: failure.value.message })
  return { run: runId, ok: false }
})
// One run at a time per component: a specialist is one worker.
return yield* locks.get(component.id)!.withPermits(1)(body)

// ctx.emit: validate against the component's declared schema, then publish
emit: (name, data) =>
  Schema.encodeUnknownEffect(component.events[name])(data).pipe(
    Effect.flatMap((encoded) => makeEvent({ type: `${component.id}/${name}`, ..., data: encoded })),
    Effect.flatMap(bus.publish))

// Event.ts: the journal events.ndjson is the bus. Any process appends; every bus tails it.
const publish = (event: AgentEvent) =>
  fs.writeFileString(journal, JSON.stringify(encode(event)) + "\n", { flag: "a" })

// Tail from the current end (never replay history as live), every 250 ms
let offset = yield* size
const poll = Effect.gen(function*() {
  const end = yield* size
  if (end < offset) offset = 0n                       // journal rotated
  if (end === offset) return
  const chunk = yield* readFrom(journal, offset, end - offset)
  const text = new TextDecoder().decode(chunk)
  const complete = text.lastIndexOf("\n") + 1        // a writer may be mid-line
  offset += byteLength(text.slice(0, complete))
  yield* PubSub.publishAll(pubsub, yield* parse(text.slice(0, complete)))
})
yield* poll.pipe(Effect.repeat(Schedule.spaced("250 millis")), Effect.forkScoped)

// subscribe = Stream.fromPubSub(pubsub); history = parse(whole file)

// Settings.ts: config.json in ~/.config/relay/atomic-agents, applied live

// effective(): config overrides on top of the code defaults
model: own.model ?? component.agent.model,
enabled: own.enabled ?? true,
cron: (job, fallback) => own.cron?.[job] ?? fallback

// set(): `use` or a config.set event. Merge-patch, validate, announce, swap.
const before = yield* read.pipe(Effect.flatMap(parse))
const after = yield* decodeValue(mergePatch(before, patch)).pipe(Effect.flatMap(validate),
  Effect.catchTag("SettingsError", (e) => reject(e.message)))   // emits config.rejected
const changes = diff(before, after)
if (changes.length === 0) return changes
yield* fs.writeFileString(temp, JSON.stringify(after, null, 2))
yield* publish("config.changed", { by, source, changes, undo: undoPatch(changes), config: after })
yield* fs.rename(temp, file)                                    // atomic swap
yield* SubscriptionRef.set(ref, after)                          // runs read this

// poll(): someone edited the file by hand (every 1 s)
const parsed = yield* Effect.result(parse(text))
if (Result.isFailure(parsed)) return yield* publish("config.rejected", ...)  // keep last good
yield* SubscriptionRef.set(ref, parsed.success)
yield* publish("config.changed", { by: "file", ... })

// Model.ts: one-shot call through omp, no tools, no repo context
if (NATIVE_ONLY.test(request.model)) return yield* fail("Anthropic and OpenAI run natively, not via OpenRouter")
if (viaOpenRouter) key = readKeyFile(OPENROUTER_API_KEY_FILE)   // only these calls get the key

const result = yield* Effect.scoped(Effect.gen(function*() {
  const cwd = yield* fs.makeTempDirectoryScoped({ prefix: "atomic-agent-" })   // empty dir
  return yield* exec("omp", [
    "-p", "--mode", "json", "--model", request.model, "--thinking", request.thinking ?? "off",
    "--no-tools", "--no-skills", "--no-rules", "--no-extensions", "--no-lsp", "--no-session",
    "--system-prompt", request.system, request.prompt
  ], { cwd, env: { OPENROUTER_API_KEY: key } })
})).pipe(Effect.timeoutOrElse({ duration: request.timeout ?? "5 minutes", orElse: () => fail("timed out") }))

const reply = lastAssistant(result.stdout)                      // last message_end + summed cost
if (reply?.message.stopReason === "error") return yield* fail(reply.message.errorMessage)
if (result.exitCode !== 0) return yield* fail(`omp exited ${result.exitCode}`)
if ((reply.message.provider === "openrouter") !== viaOpenRouter) return yield* fail("served by the wrong provider")
return { text, model, provider, seconds, cost }

// prop-render/component.ts: the render job
triggers: [Manual, OnEvent("prop-render/render.requested"), Cron("0 9 * * *", subjectOfTheDay)],

run: function*({ subject }, ctx) {
  let prompt = `Model this object: ${subject}`
  for (let attempt = 1; ; attempt++) {
    const reply = yield* models.generate({ model: ctx.model, system: ctx.agent.system, prompt, thinking: ctx.agent.thinking })
    cost += reply.cost
    const code = extractPythonBlock(reply.text) ?? reply.text
    const script = path.join(ctx.runDir, `build-${attempt}.py`)
    yield* fs.writeFileString(script, code)
    const outcome = yield* Effect.result(blender.render(script, image, glb))   // the tool
    if (Result.isSuccess(outcome))
      return yield* ctx.emit("render.completed", { subject, model: ctx.model, image, glb, script, attempts: attempt, seconds, cost })
    if (attempt === MAX_ATTEMPTS) return yield* outcome.failure                 // 2 tries
    // One repair turn: the model sees its own script and Blender's traceback.
    prompt = `Model this object: ${subject}\n\nYour previous script failed in Blender:\n${code}\nError:\n${outcome.failure.log}\n\nReturn the corrected script.`
  }
}

// Blender tool: headless, never takes focus, 3 min timeout
exec(blender, ["-b", "--factory-startup", "-noaudio", "--python-exit-code", "1", "--python", STAGE, "--", script, image, glb])
